INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l1',4,1,1,'Finding Fossil Man','发现化石人','定语从句(that/who/where 关系词)、过去分词作定语(handed down / buried in rock)、疑问词引导的宾语从句(where…came from / what they did)、may have done(对过去的推测)+ 现在完成时对比、比较级(easier…than)/ neither…nor(NCE4 无 KS 页,考点由课文结构自取;原创承载·论如何从口传萨迦与石器认识没有文字的史前民族·题材科普无害;美语化 artifact/gray;第四册开篇课)','我们怎样了解那些远在文字出现之前就生活过的人?世界上只有少数地方在几千年前就开始书写,那里发生的事我们今天还能读到。可在许多地方,当时没人留下任何文字,一个民族保存历史的唯一办法,就是把它当作萨迦口口相传——那是代代相传的漫长传说。这类传说很有用,因为它们能告诉我们一些关于古代民族迁徙的情况,而那些民族并没有留下任何文字记录。有些人类学家想弄清:如今生活在太平洋岛屿上的波利尼西亚人,其遥远的祖先究竟来自何处;他们在这些口头传说里找到了部分答案——传说表明,其中一些人早在许多世纪前就从印度尼西亚渡海而来。可是那些最早的、与我们十分相像的人,已被遗忘了;他们的萨迦——如果曾经有过的话——也已失传。于是考古学家既无历史、也无传说可循,难以查明最早的人类来自哪里。偶尔会有一根骨头以化石的形式保存在岩石里,但这样的发现十分罕见。所幸,那些远古的人用石头、尤其是燧石打制工具,因为燧石比多数别的石头更容易加工;他们也许还用过木头和兽皮,只是这些早已腐烂殆尽。石头不会腐坏,所以那些很久以前打制的工具留存了下来,尽管打制它们的男男女女连骨头都已消失得无影无踪。仅凭一把加工过的燧石,考古学家就能讲出一段任何传说都不曾保留的故事。','{"q":"Listen and answer — Why are legends handed down by storytellers useful?","options":["They tell us about the migrations of peoples who left no written record","They are always perfectly accurate","They make writing unnecessary","They are simply entertaining"],"answer_index":0}'::jsonb,'{"title":"定语从句 / 过去分词作定语 / 疑问词宾语从句 / may have done","intro":"①定语从句由 that/who/which/where 引导,修饰前面的名词:things that happened; people who lived long ago。②过去分词作定语,表被动/完成:legends handed down; a bone buried in rock。③疑问词(where/what/how)引导宾语从句,用陈述语序:wondered where they came from。④may + have + 过去分词,对过去作推测:they may have used wood。⑤比较级 easier…than;neither…nor“既不…也不…”。","table":{"headers":["用法","结构","例子"],"rows":[["定语从句","名词 + that/who/where","things that happened long ago"],["过去分词作定语","名词 + done","legends handed down"],["疑问词宾语从句","wonder + where/what + 陈述语序","wondered where they came from"],["对过去的推测","may + have + 过去分词","they may have used wood"]]},"specialRules":[{"rule":"疑问词引导宾语从句时用陈述语序(主语在前),不倒装、不加问号:wondered where the ancestors came from。","mark":"where they came from(不是 where did they come)"},{"rule":"过去分词作定语=被动/完成(handed down 被传下、buried 被埋);现在分词作定语=主动/进行。","mark":"handed down / buried in rock"},{"rule":"美式拼写:artifact(器物,英式 artefact)、gray(灰色,英式 grey)。本课已按美语写。","mark":"artifact / gray"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l1',1,NULL,'How do we learn about people who lived long before anyone could write? In a few parts of the world writing began thousands of years ago, and we can read of things that happened in those distant times. Yet in many places no one wrote anything down, and the only way that a people could keep its history was to recount it aloud, as sagas — long legends handed down from one generation to the next.','我们怎样了解那些远在文字出现之前就生活过的人?世界上只有少数地方在几千年前就开始书写,那里发生的事我们今天还能读到。可在许多地方,当时没人留下任何文字,一个民族保存历史的唯一办法,就是把它当作萨迦口口相传——那是代代相传的漫长传说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l1',2,NULL,'Such legends are useful, because they can tell us something about the migrations of peoples who lived long ago but left no written record. Anthropologists who wondered where the distant ancestors of the Polynesian islanders came from found part of the answer in these spoken tales, which suggest that some of them sailed from Indonesia many centuries ago.','这类传说很有用,因为它们能告诉我们一些关于古代民族迁徙的情况,而那些民族并没有留下任何文字记录。有些人类学家想弄清:太平洋岛上的波利尼西亚人,其遥远的祖先究竟来自何处;他们在这些口头传说里找到了部分答案——传说表明,其中一些人早在许多世纪前就从印度尼西亚渡海而来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l1',3,NULL,'But the very first people, who were much like ourselves, are forgotten, and their sagas, if they ever had any, are lost. So archaeologists have neither history nor legend to help them find out where the earliest humans came from. Now and then a bone survives as a fossil, buried in rock, but such finds are rare.','可是那些最早的、与我们十分相像的人,已被遗忘了;他们的萨迦——如果曾经有过的话——也已失传。于是考古学家既无历史、也无传说可循,难以查明最早的人类来自哪里。偶尔会有一根骨头以化石的形式保存在岩石里,但这样的发现十分罕见。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l1',4,NULL,'Fortunately, those early people made tools of stone, especially flint, which is easier to shape than most other kinds; they may also have used wood and animal skins, but these have long since rotted away. Stone does not decay, and so the tools that were made so long ago have remained, even though the bones of the men and women who made them have disappeared without a trace. From a handful of worked flints an archaeologist can recount a story that no legend preserved.','所幸,那些远古的人用石头、尤其是燧石打制工具,因为燧石比多数别的石头更容易加工;他们也许还用过木头和兽皮,只是这些早已腐烂殆尽。石头不会腐坏,所以那些很久以前打制的工具留存了下来,尽管打制它们的男男女女连骨头都已消失得无影无踪。仅凭一把加工过的燧石,考古学家就能讲出一段任何传说都不曾保留的故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
