INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l3','cut off from','',NULL,'/kʌt ɔːf frəm/','The villages were cut off from the world.','那些村子与世隔绝。','The storm cut us off from town.','暴风雪使我们与城镇断了联系。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l3','go out of one''s way','',NULL,'/ɡoʊ aʊt əv wʌnz weɪ/','They did not go out of their way to court danger.','他们并不刻意去招惹危险。','She went out of her way to help me.','她特地费心来帮我。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l3','take shelter','',NULL,'/teɪk ˈʃeltər/','Climbers took shelter with a shepherd.','登山者在牧人处避身。','We took shelter from the rain.','我们避了雨。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l3','little more than','',NULL,'/ˈlɪtəl mɔːr ðæn/','The food was little more than cheese and bread.','吃的不过是奶酪和面包而已。','It was little more than a hut.','那不过是间小棚屋罢了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp1','choice','{"stem":"\"___ is hard for us to realize how tough their life was.\"(it 形式主语,填代词)","options":["This","That","There","It"],"answer_index":3,"stem_cn":"我们很难体会他们的生活多么艰苦。","explanation_cn":"It 作形式主语,真正主语是后面的不定式 to realize…。✓ It is hard for us to realize… ✗ That / This / There:形式主语用 It。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp1','choice','{"stem":"\"It is hard for us ___ realize how difficult it was for them.\"(it 形式主语,真正主语是后面的不定式,填不定式符号)","options":["of","that","to","for"],"answer_index":2,"stem_cn":"我们很难体会那对他们有多难。","explanation_cn":"it 形式主语句,真正主语是不定式;填不定式符号 to。✓ It is hard for us to realize how… ✗ for / of / that:此处用 to realize。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp1','choice','{"stem":"\"It was hard ___ the pioneers to find a decent inn.\"(it 形式主语句:动作的执行者用哪个介词引出)","options":["of","with","to","for"],"answer_index":3,"stem_cn":"对先驱者来说,找一家像样的客栈很难。","explanation_cn":"it 形式主语句,动作的执行者用 for sb 引出(不用 of sb)。✓ It was hard for the pioneers to find an inn. ✗ of / to / with:此结构用 for。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp2','choice','{"stem":"\"The change to those poor valleys ___ have been hard for them.\"(对过去的推测“一定…”,填情态词)","options":["would","can","must","need"],"answer_index":2,"stem_cn":"搬到那些贫穷的山谷,对他们来说一定很难熬。","explanation_cn":"对过去的肯定推测“一定…了”用 must + have + 过去分词。✓ must have been hard for them. ✗ can / would / need:表推测用 must。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp2','choice','{"stem":"\"The first climbers ___ have suffered greatly on the way up.\"(对过去的推测,填表推测的词)","options":["must","shall","dare","ought"],"answer_index":0,"stem_cn":"最早的登山者上山途中一定吃了不少苦。","explanation_cn":"对过去的肯定推测,填 must。✓ The first climbers must have suffered greatly. ✗ shall / ought(须加 to)/ dare:表推测“一定”用 must。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp2','choice','{"stem":"\"Reaching the summit must ___ felt like a triumph.\"(must ___ 过去分词:对过去的推测,填这个助动词)","options":["has","had","having","have"],"answer_index":3,"stem_cn":"登上顶峰一定感觉像大获全胜。","explanation_cn":"must + have + 过去分词构成对过去的推测;填助动词 have。✓ must have felt like a triumph. ✗ has / had / having:must 后一律用 have + 过去分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp3','choice','{"stem":"\"The villages were poor settlements, ___ off from the world.\"(过去分词作定语,被动“被隔绝”)","options":["cuts","to cut","cut","cutting"],"answer_index":2,"stem_cn":"那些村子是与世隔绝的贫穷聚落。","explanation_cn":"过去分词作定语,表被动“被隔绝”,修饰 settlements。✓ settlements cut off from the world. ✗ cutting(主动)/ cuts / to cut:表被动用过去分词 cut。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp3','choice','{"stem":"\"Men ___ to comfortable homes found the valleys hard.\"(过去分词作定语,“习惯于…的”)","options":["accustomed","accustoming","accustom","to accustom"],"answer_index":0,"stem_cn":"住惯了舒适家宅的人觉得山谷难挨。","explanation_cn":"过去分词作定语,“习惯于…的”,修饰 Men。✓ Men accustomed to comfortable homes. ✗ accustoming / accustom / to accustom:此处用过去分词 accustomed。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp3','choice','{"stem":"\"The bread was ___ down with rough wine.\"(过去分词,被动“被…送下”)","options":["wash","to wash","washing","washed"],"answer_index":3,"stem_cn":"面包就着劣酒咽下。","explanation_cn":"过去分词,被动“被…送下”。✓ the bread was washed down with wine. ✗ washing(主动)/ wash / to wash:被动用过去分词 washed。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp4','choice','{"stem":"\"The summit was the prize ___ the climbers wanted most.\"(定语从句,指物,作宾语)","options":["what","whose","that","who"],"answer_index":2,"stem_cn":"顶峰是登山者最想要的奖赏。","explanation_cn":"定语从句,先行词 prize 指物,that 作从句宾语(可省)。✓ the prize that the climbers wanted. ✗ who(指人)/ what / whose:指物用 that。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp4','choice','{"stem":"\"They faced dangers ___ would make us shudder.\"(定语从句,指物,作主语)","options":["that","what","who","whose"],"answer_index":0,"stem_cn":"他们面对的危险会让我们不寒而栗。","explanation_cn":"定语从句,先行词 dangers 指物,that 作从句主语。✓ dangers that would make us shudder. ✗ who / what / whose:指物用 that。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp4','choice','{"stem":"\"Such inns ___ there were tended to be dirty.\"(such … ___ 结构:‘…这样的’,填与 such 呼应的词)","options":["that","which","as","than"],"answer_index":2,"stem_cn":"仅有的那些客栈往往很脏。","explanation_cn":"such … as … 结构,“…这样的/仅有的那些…”;与 such 呼应用 as。✓ Such inns as there were. ✗ that / which / than:与 such 搭配用 as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp5','choice','{"stem":"\"The harder the route, the more it ___ admired today.\"(一般现在时的被动,填 be 动词单数)","options":["was","is","has","had"],"answer_index":1,"stem_cn":"路线越难,如今就越受推崇。","explanation_cn":"一般现在时的被动 is + 过去分词。✓ the more it is admired today. ✗ was(过去)/ has / had:现在被动用 is。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp5','choice','{"stem":"\"The peak had never ___ attained before their climb.\"(过去完成的被动:had never + ___ + 过去分词,填中间的词)","options":["was","being","been","be"],"answer_index":2,"stem_cn":"在他们登顶前,那座峰从未被征服过。","explanation_cn":"过去完成的被动 = had + been + 过去分词;填中间的 been。✓ had never been attained before. ✗ be / being / was:had 后用 been + 过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp5','choice','{"stem":"\"The Matterhorn was finally ___ in 1865.\"(一般过去时的被动:was + 过去分词,填过去分词)","options":["attaining","attained","attains","attain"],"answer_index":1,"stem_cn":"马特霍恩峰终于在1865年被征服。","explanation_cn":"一般过去时的被动 was + 过去分词。✓ The Matterhorn was finally attained in 1865. ✗ attain / attaining / attains:was 后用过去分词 attained。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp6','choice','{"stem":"\"The highest point of a mountain is its ___.\"(“顶峰”用哪个词)","options":["slope","valley","base","summit"],"answer_index":3,"stem_cn":"一座山的最高点。","explanation_cn":"一座山的最高点是 summit。✓ the summit itself was the prize. ✗ base 山脚;✗ slope 山坡;✗ valley 山谷——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp6','choice','{"stem":"\"Full of danger and risk means ___.\"(“危险的”用哪个词)","options":["perilous","peaceful","gentle","ordinary"],"answer_index":0,"stem_cn":"充满危险与风险的。","explanation_cn":"充满危险与风险的是 perilous。✓ dangers of the most perilous kind. ✗ peaceful 平静;✗ gentle 温和;✗ ordinary 普通——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',5,'am4_l3_gp6','choice','{"stem":"\"A person who is among the first to do something is a ___.\"(“先驱”用哪个词)","options":["follower","pioneer","servant","stranger"],"answer_index":1,"stem_cn":"最早做某事的人之一。","explanation_cn":"最早做某事的人之一是 pioneer。✓ difficult things were for those pioneers. ✗ follower 追随者;✗ stranger 陌生人;✗ servant 仆人——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"summit 的意思是:","options":["山谷","顶峰","山坡","山脚"],"answer_index":1,"explanation_cn":"summit = 顶峰。✓ the summit was the prize 顶峰是奖赏。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"attain 的意思是:","options":["达到,获得","避免","失去","忘记"],"answer_index":0,"explanation_cn":"attain = 达到、登上、获得。✓ had never been attained before 从未被征服。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"perilous 的意思是:","options":["普通的","温和的","平静的","危险的"],"answer_index":3,"explanation_cn":"perilous = 危险的。✓ the most perilous kind 最凶险的一类。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"shudder 的意思是:","options":["歌唱","大笑","发抖,战栗","微笑"],"answer_index":2,"explanation_cn":"shudder = 发抖、战栗。✓ make a modern alpinist shudder 让今人不寒而栗。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"solitary 的意思是:","options":["单独的,唯一的","众多的","热闹的","常见的"],"answer_index":0,"explanation_cn":"solitary = 单独的、唯一的。✓ one solitary objective 唯一的目标。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',6,NULL,'choice','{"stem":"impoverish 的意思是:","options":["使快乐","使强壮","使富有","使贫穷"],"answer_index":3,"explanation_cn":"impoverish = 使贫穷。✓ these impoverished valleys 一贫如洗的山谷。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',7,NULL,'cloze','{"stem":"第 1 空","context":"Modern climbers seek the hardest route, and the harder it is, the more it ___1___ admired. The pioneers, however, wanted only the summit, especially one that had never ___2___ attained. It is hard for us ___3___ realize how tough their life was. The change to those poor valleys must ___4___ been hard.","blank_no":1,"options":["is","was","has","are"],"answer_index":0,"explanation_cn":"一般现在时的被动 is + 过去分词。✓ the more it is admired."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',7,NULL,'cloze','{"stem":"第 2 空","context":"Modern climbers seek the hardest route, and the harder it is, the more it ___1___ admired. The pioneers, however, wanted only the summit, especially one that had never ___2___ attained. It is hard for us ___3___ realize how tough their life was. The change to those poor valleys must ___4___ been hard.","blank_no":2,"options":["been","be","being","was"],"answer_index":0,"explanation_cn":"过去完成的被动 had never been + 过去分词。✓ one that had never been attained."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',7,NULL,'cloze','{"stem":"第 3 空","context":"Modern climbers seek the hardest route, and the harder it is, the more it ___1___ admired. The pioneers, however, wanted only the summit, especially one that had never ___2___ attained. It is hard for us ___3___ realize how tough their life was. The change to those poor valleys must ___4___ been hard.","blank_no":3,"options":["to","for","of","that"],"answer_index":0,"explanation_cn":"it 句型里真正主语是不定式,填 to。✓ It is hard for us to realize…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',7,NULL,'cloze','{"stem":"第 4 空","context":"Modern climbers seek the hardest route, and the harder it is, the more it ___1___ admired. The pioneers, however, wanted only the summit, especially one that had never ___2___ attained. It is hard for us ___3___ realize how tough their life was. The change to those poor valleys must ___4___ been hard.","blank_no":4,"options":["have","has","had","be"],"answer_index":0,"explanation_cn":"must + have + 过去分词,对过去的推测。✓ the change must have been hard."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',8,NULL,'choice','{"stem":"What was the main objective of early mountain climbers?","options":["To enjoy good sport","To find the most difficult route","To explore Alpine villages","To reach the summit, especially one never climbed before"],"answer_index":3,"explanation_cn":"录音说早期登山者的主要目标是登顶,尤其是登上从未有人征服过的顶峰。✓ reach the summit never climbed before."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',8,NULL,'choice','{"stem":"How did the early climbers differ from modern alpinists?","options":["They wanted the easiest way up, not the hardest","They avoided all danger","They used modern equipment","They climbed only in summer"],"answer_index":0,"explanation_cn":"录音说与今人求难度不同,先驱者找的是登顶最容易的路。✓ easiest way up."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',8,NULL,'choice','{"stem":"What were the Alpine villages like in the pioneering days?","options":["Full of fine hotels","Poor and cut off from the world","Modern and clean","Rich and crowded"],"answer_index":1,"explanation_cn":"录音说当年阿尔卑斯的村庄贫穷、偏远,被高峰隔绝于世界之外。✓ poor and cut off."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',9,NULL,'choice','{"stem":"你想说\"我们很难体会那对他们有多难\"(it 形式主语):","options":["It is hard for us to realize how difficult it was for them.","Is hard for us to realize how difficult it was for them.","It is hard of us to realize how difficult it was for them.","It is hard for us realize how difficult it was for them."],"answer_index":0,"explanation_cn":"句首用 It 占位,真正的内容是后面的不定式 to realize…;执行者用 for us 引出;不省 to、句首不省 It、不用 of us。✓ It is hard for us to realize… 场合:说“对我们来说,要…很难”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',9,NULL,'choice','{"stem":"你想说\"搬到那些贫穷的山谷,对他们来说一定很难熬\"(对过去的推测):","options":["The change to those poor valleys must have be hard for them.","The change to those poor valleys must be hard for them.","The change to those poor valleys must have been hard for them.","The change to those poor valleys must to have been hard for them."],"answer_index":2,"explanation_cn":"对过去的推测 must + have + been + hard;不用 must be(表现在)、不用 must to have、been 不能变 be。✓ must have been hard. 场合:推断过去“一定…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',9,NULL,'choice','{"stem":"你想说\"那些村子是与世隔绝的贫穷聚落\"(过去分词作定语):","options":["The villages were poor settlements to cut off from the world.","The villages were poor settlements which cut off from the world.","The villages were poor settlements cutting off from the world.","The villages were poor settlements cut off from the world."],"answer_index":3,"explanation_cn":"过去分词 cut off 作后置修饰,表被动“被隔绝”;不用 cutting(主动)、不加 which、不用 to cut。✓ settlements cut off from the world. 场合:说“与…隔绝的…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"summit 的意思是:","options":["山谷","山脚","山坡","顶峰"],"answer_index":3,"explanation_cn":"summit = 顶峰。✓ the summit was the prize."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"perilous 的意思是:","options":["危险的","普通的","平静的","温和的"],"answer_index":0,"explanation_cn":"perilous = 危险的。✓ the most perilous kind."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"\"___ is hard for us to realize how tough their life was.\"(it 形式主语)","options":["There","It","This","That"],"answer_index":1,"stem_cn":"我们很难体会他们的生活多么艰苦。","explanation_cn":"It 作形式主语,真正主语是后面的不定式。✓ It is hard for us to realize… ✗ That / This / There。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"\"The change must ___ been hard for them.\"(对过去的推测:must ___ 过去分词,填助动词)","options":["has","had","be","have"],"answer_index":3,"stem_cn":"那份落差对他们来说一定很难熬。","explanation_cn":"must + have + 过去分词,对过去的推测。✓ the change must have been hard. ✗ has / had / be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"\"cut off from\" 的意思是:","options":["连接到","靠近","与…隔绝","属于"],"answer_index":2,"explanation_cn":"cut off from = 与…隔绝。✓ cut off from the world."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"\"take shelter\" 的意思是:","options":["躲避、找地方避身","迷路","起程","分享食物"],"answer_index":0,"explanation_cn":"take shelter = 躲避、找地方避身。✓ climbers took shelter with a shepherd."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"Why did the early climbers choose the easiest route to the top?","options":["The hard routes were closed","They had no equipment","They were afraid of heights","The summit itself, not the difficulty, was the prize they sought"],"answer_index":3,"passage":"Modern climbers seek out mountains by the hardest route they can find, and the more difficult the climb, the more highly it is admired. In the early days it was not like this at all. The pioneers looked for the easiest way to the top, because the summit itself was the prize they wanted, especially if it had never been attained before. The Matterhorn, unclimbed for so long, was the greatest prize of all. It is true that on their expeditions those early climbers often met dangers of the most perilous kind, equipped in a way that would make a modern alpinist shudder; but they did not go out of their way to court such risks. They had a single aim, one solitary objective — the top. It is hard for us today to realize how difficult things were for those pioneers. Except for one or two places, such as Zermatt and Chamonix, that had quickly grown popular, the Alpine villages were poor, remote settlements, cut off from the world by the high peaks. Such inns as there were tended to be dirty; the food was little more than local cheese and bread, often washed down with rough wine. Often a valley boasted no inn at all, and climbers took shelter wherever they could — sometimes with the village priest, who was usually as poor as his neighbors. Everywhere the background was the same: dirt, poverty, and hard living. For men accustomed to comfortable homes, the change to these impoverished valleys must have been hard indeed. Yet they came, year after year, because a summit that no one had yet reached was worth any discomfort.","explanation_cn":"课文说先驱者选最容易的路,因为顶峰本身、而非难度,才是他们追求的奖赏。✓ the summit was the prize."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"What was the food usually like at Alpine inns in those days?","options":["Fresh fruit and meat","Little more than local cheese and bread with rough wine","Nothing at all","Rich seven-course dinners"],"answer_index":1,"passage":"Modern climbers seek out mountains by the hardest route they can find, and the more difficult the climb, the more highly it is admired. In the early days it was not like this at all. The pioneers looked for the easiest way to the top, because the summit itself was the prize they wanted, especially if it had never been attained before. The Matterhorn, unclimbed for so long, was the greatest prize of all. It is true that on their expeditions those early climbers often met dangers of the most perilous kind, equipped in a way that would make a modern alpinist shudder; but they did not go out of their way to court such risks. They had a single aim, one solitary objective — the top. It is hard for us today to realize how difficult things were for those pioneers. Except for one or two places, such as Zermatt and Chamonix, that had quickly grown popular, the Alpine villages were poor, remote settlements, cut off from the world by the high peaks. Such inns as there were tended to be dirty; the food was little more than local cheese and bread, often washed down with rough wine. Often a valley boasted no inn at all, and climbers took shelter wherever they could — sometimes with the village priest, who was usually as poor as his neighbors. Everywhere the background was the same: dirt, poverty, and hard living. For men accustomed to comfortable homes, the change to these impoverished valleys must have been hard indeed. Yet they came, year after year, because a summit that no one had yet reached was worth any discomfort.","explanation_cn":"课文说当年客栈的吃食不过是本地奶酪和面包,常就着劣酒咽下。✓ cheese and bread with rough wine."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"What single goal did the pioneering climbers have?","options":["Studying the villages","Meeting other climbers","Finding good sport","Reaching the top"],"answer_index":3,"audio":"Modern climbers seek out mountains by the hardest route they can find, and the more difficult the climb, the more highly it is admired. In the early days it was not like this at all. The pioneers looked for the easiest way to the top, because the summit itself was the prize they wanted, especially if it had never been attained before. The Matterhorn, unclimbed for so long, was the greatest prize of all. It is true that on their expeditions those early climbers often met dangers of the most perilous kind, equipped in a way that would make a modern alpinist shudder; but they did not go out of their way to court such risks. They had a single aim, one solitary objective — the top. It is hard for us today to realize how difficult things were for those pioneers. Except for one or two places, such as Zermatt and Chamonix, that had quickly grown popular, the Alpine villages were poor, remote settlements, cut off from the world by the high peaks. Such inns as there were tended to be dirty; the food was little more than local cheese and bread, often washed down with rough wine. Often a valley boasted no inn at all, and climbers took shelter wherever they could — sometimes with the village priest, who was usually as poor as his neighbors. Everywhere the background was the same: dirt, poverty, and hard living. For men accustomed to comfortable homes, the change to these impoverished valleys must have been hard indeed. Yet they came, year after year, because a summit that no one had yet reached was worth any discomfort.","explanation_cn":"课文说先驱者只有一个目标——登顶。✓ reaching the top."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l3',10,NULL,'choice','{"stem":"How would a modern alpinist react to the pioneers'' equipment?","options":["They would copy it","They would not notice","It would make them shudder","They would admire it"],"answer_index":2,"audio":"Modern climbers seek out mountains by the hardest route they can find, and the more difficult the climb, the more highly it is admired. In the early days it was not like this at all. The pioneers looked for the easiest way to the top, because the summit itself was the prize they wanted, especially if it had never been attained before. The Matterhorn, unclimbed for so long, was the greatest prize of all. It is true that on their expeditions those early climbers often met dangers of the most perilous kind, equipped in a way that would make a modern alpinist shudder; but they did not go out of their way to court such risks. They had a single aim, one solitary objective — the top. It is hard for us today to realize how difficult things were for those pioneers. Except for one or two places, such as Zermatt and Chamonix, that had quickly grown popular, the Alpine villages were poor, remote settlements, cut off from the world by the high peaks. Such inns as there were tended to be dirty; the food was little more than local cheese and bread, often washed down with rough wine. Often a valley boasted no inn at all, and climbers took shelter wherever they could — sometimes with the village priest, who was usually as poor as his neighbors. Everywhere the background was the same: dirt, poverty, and hard living. For men accustomed to comfortable homes, the change to these impoverished valleys must have been hard indeed. Yet they came, year after year, because a summit that no one had yet reached was worth any discomfort.","explanation_cn":"课文说先驱者的装备简陋得会让今天的登山家不寒而栗。✓ make a modern alpinist shudder."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l4',4,1,4,'Seeing Hands','会看东西的手','定语从句(who/which/that,并列关系词 who…but who…)、被动语态各时态(have been reported / was noticed / was given)、现在分词短语作状语(moving…, wearing…)、be able to do + the moment 引导时间从句、疑问词引导的宾语从句(why…, how…, where…)(NCE4 无 KS 页,考点由课文结构自取;原创承载·一名视力正常却能用皮肤感知形状与颜色的少女受科学委员会测试的奇闻·题材科普无害;为 IP 洁净化用原创虚构人物与情节;美语化 color/gray;第四册第4课)','近些年,有人报道了几起怪事:某些人似乎能用指尖辨别颜色,甚至能感知藏在一堵实墙后面的物体。其中最不可思议的一例,说的是一个名叫娜迪亚的小姑娘——她视力完全正常,却还能透过手上的皮肤感知形状和颜色。她这份异能最早是被母亲注意到的。一天下午,娜迪亚把手放在一只小保险箱关着的门上,毫不迟疑地说出了锁在里面的硬币,还问为什么那儿存了那么多旧硬币。她这份天赋的消息很快传到一群科学家那里;春天,一个专门的委员会给她做了一长串测试。测试中,她能隔着一块不透明的屏读出印在纸上的字;更奇的是,她把胳膊肘在一叠彩色卡片上缓缓移动,竟一张张准确报出颜色。在另一项测试里,她戴着厚手套,用一根手指描出了藏在地毯下面那幅画的轮廓。科学家发现,她的膝盖和肩膀也有类似的敏感度。整个测试过程中娜迪亚都被蒙着眼;事实上,只要不蒙眼,她似乎就完全失去了这种能力。人们还发现:尽管她能用手指感知,可她的手一沾湿,这能力就立刻停止了。','{"q":"Listen and answer — How did the girl discover she had this unusual gift?","options":["Her mother noticed it when she laid her hand on a closed safe","She read about it in a newspaper","A teacher pointed it out","She saw it in a dream"],"answer_index":0}'::jsonb,'{"title":"定语从句 / 被动各时态 / 现在分词作状语 / be able to do·the moment","intro":"①定语从句 who/which/that 修饰名词;并列时可 who…but who…。②被动语态各时态:have been reported(现在完成)/ was noticed(过去)/ was given(过去)。③现在分词短语作状语,表伴随/方式:Moving her elbow…, she named…。④be able to do=能够做;the moment=“一…就…”,引导时间从句。⑤疑问词 why/how/where 引导宾语从句,用陈述语序。","table":{"headers":["用法","结构","例子"],"rows":[["定语从句","名词 + who/which/that","people who can detect colors"],["被动各时态","have been / was + 过去分词","cases have been reported"],["现在分词作状语","doing …, 主句","Moving her elbow, she named…"],["the moment 时间从句","the moment + 句子","ceased the moment her hands were wet"]]},"specialRules":[{"rule":"现在完成的被动=have/has + been + 过去分词:cases have been reported。","mark":"have been reported"},{"rule":"the moment / the instant 相当于 as soon as,引导时间从句,“一…就…”。","mark":"the moment her hands were wet"},{"rule":"美式拼写:color(颜色,英式 colour)、gray(灰色,英式 grey)。本课已按美语写。","mark":"color / gray"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l4',1,NULL,'In recent years several strange cases have been reported of people who seem able to detect colors with their fingertips, or even to sense objects hidden behind a solid wall. One of the most remarkable concerns a young girl named Nadia, who has perfectly normal vision but who can also perceive shapes and colors through the skin of her hands.','近些年,有人报道了几起怪事:某些人似乎能用指尖辨别颜色,甚至能感知藏在一堵实墙后面的物体。其中最不可思议的一例,说的是一个名叫娜迪亚的小姑娘——她视力完全正常,却还能透过手上的皮肤感知形状和颜色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l4',2,NULL,'Her unusual gift was first noticed by her mother. One afternoon Nadia laid her hand on the closed door of a small safe and, without hesitation, described the coins locked inside and asked why so many old ones had been kept there.','她这份异能最早是被母亲注意到的。一天下午,娜迪亚把手放在一只小保险箱关着的门上,毫不迟疑地说出了锁在里面的硬币,还问为什么那儿存了那么多旧硬币。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l4',3,NULL,'Word of her talent soon reached a group of scientists, and in the spring she was given a long series of tests by a special commission. During these tests she was able to read a page of print through an opaque screen; and, stranger still, moving her elbow slowly over a set of colored cards, she named each color correctly.','她这份天赋的消息很快传到一群科学家那里;春天,一个专门的委员会给她做了一长串测试。测试中,她能隔着一块不透明的屏读出印在纸上的字;更奇的是,她把胳膊肘在一叠彩色卡片上缓缓移动,竟一张张准确报出颜色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l4',4,NULL,'In another test, wearing thick gloves, she traced with one finger the outline of a picture that had been hidden beneath a rug. The scientists found that her knees and shoulders showed a similar sensitivity.','在另一项测试里,她戴着厚手套,用一根手指描出了藏在地毯下面那幅画的轮廓。科学家发现,她的膝盖和肩膀也有类似的敏感度。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l4',5,NULL,'Throughout every trial Nadia was blindfolded; indeed, unless she was blindfolded she seemed to lose the power altogether. It was also discovered that, although she could perceive things with her fingers, the ability ceased the moment her hands were wet.','整个测试过程中娜迪亚都被蒙着眼;事实上,只要不蒙眼,她似乎就完全失去了这种能力。人们还发现:尽管她能用手指感知,可她的手一沾湿,这能力就立刻停止了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
