INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l4','make out','',NULL,'/meɪk aʊt/','She could make out the outline under the rug.','她能辨认出地毯下的轮廓。','I could just make out his face in the dark.','黑暗中我勉强能看清他的脸。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l4','a series of','',NULL,'/ə ˈsɪriːz əv/','She was given a series of tests.','她接受了一连串测试。','A series of accidents followed.','接连发生了一系列事故。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l4','lay one''s hand on','',NULL,'/leɪ wʌnz hænd ɑːn/','She laid her hand on the safe.','她把手放在保险箱上。','He laid his hand on my shoulder.','他把手搭在我肩上。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l4','come to light','',NULL,'/kʌm tə laɪt/','Her strange gift soon came to light.','她奇特的天赋很快为人所知。','New facts came to light later.','后来又有新的事实被发现。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp1','choice','{"stem":"\"The report concerns people ___ can detect colors with their fingers.\"(定语从句,指人,作主语)","options":["what","who","which","whose"],"answer_index":1,"stem_cn":"报告说的是能用手指辨色的人。","explanation_cn":"定语从句,先行词 people 指人,who 作从句主语。✓ people who can detect colors. ✗ which(指物)/ what / whose:指人作主语用 who。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp1','choice','{"stem":"\"Nadia has normal vision but ___ can also perceive through her skin.\"(定语从句,并列关系词,指人)","options":["what","which","who","whom"],"answer_index":2,"stem_cn":"娜迪亚视力正常,却还能用皮肤感知。","explanation_cn":"并列的定语从句(…but who…),先行词是 Nadia 指人,who 作从句主语。✓ but who can also perceive… ✗ which / what / whom:指人作主语用 who。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp1','choice','{"stem":"\"She traced the outline of a picture ___ had been hidden under a rug.\"(定语从句,指物,作主语)","options":["who","whose","what","that"],"answer_index":3,"stem_cn":"她描出了藏在地毯下那幅画的轮廓。","explanation_cn":"定语从句,先行词 picture 指物,that 作从句主语。✓ a picture that had been hidden. ✗ who(指人)/ what / whose:指物用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp2','choice','{"stem":"\"Several strange cases ___ been reported in recent years.\"(现在完成的被动:___ + been + 过去分词,填助动词)","options":["have","was","are","has"],"answer_index":0,"stem_cn":"近年来报道了几起怪事。","explanation_cn":"现在完成的被动 = have + been + 过去分词;主语 cases 复数用 have。✓ cases have been reported. ✗ has(单数)/ was / are:复数现在完成用 have been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp2','choice','{"stem":"\"Her gift was first ___ by her mother.\"(一般过去被动:was + 过去分词,填过去分词)","options":["noticing","notice","notices","noticed"],"answer_index":3,"stem_cn":"她的天赋最初是被母亲注意到的。","explanation_cn":"一般过去时的被动 was + 过去分词。✓ Her gift was first noticed. ✗ notice / noticing / notices:was 后用过去分词 noticed。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp2','choice','{"stem":"\"She was ___ a long series of tests by a commission.\"(一般过去被动:was + 过去分词“被给予”)","options":["giving","give","given","gave"],"answer_index":2,"stem_cn":"一个委员会给她做了一长串测试。","explanation_cn":"一般过去时的被动 was + 过去分词“被给予”。✓ She was given a series of tests. ✗ give / giving / gave:was 后用过去分词 given。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp3','choice','{"stem":"\"___ her elbow over the cards, she named each color.\"(现在分词作状语,主动“移动…”)","options":["To move","Moved","Move","Moving"],"answer_index":3,"stem_cn":"她把胳膊肘在卡片上移动,叫出每种颜色。","explanation_cn":"现在分词短语作状语,主动“移动…”,与主句同时发生。✓ Moving her elbow…, she named… ✗ Moved(被动/过去)/ Move / To move:主动伴随用 -ing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp3','choice','{"stem":"\"___ thick gloves, she traced the hidden outline.\"(现在分词作状语,“戴着…”)","options":["Wearing","To wear","Wear","Worn"],"answer_index":0,"stem_cn":"戴着厚手套,她描出了隐藏的轮廓。","explanation_cn":"现在分词短语作状语,“戴着…”。✓ Wearing thick gloves, she traced… ✗ Worn(被动)/ Wear / To wear:主动伴随用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp3','choice','{"stem":"\"She read the page, ___ her fingers lightly over it.\"(现在分词作伴随状语)","options":["run","ran","running","to run"],"answer_index":2,"stem_cn":"她指尖轻拂纸面,读出了那一页。","explanation_cn":"现在分词作伴随状语,“(手指)轻拂着…”。✓ running her fingers over it. ✗ run / ran / to run:伴随用 -ing running。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp4','choice','{"stem":"\"During the tests she was ___ to read through an opaque screen.\"(be ___ to do:能够做某事,填这个形容词)","options":["ableness","able","ability","enable"],"answer_index":1,"stem_cn":"测试中她能隔着不透明的屏读字。","explanation_cn":"be able to do,“能够做某事”;用形容词 able。✓ she was able to read… ✗ ability(名词)/ ableness / enable(动词):此结构用 able。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp4','choice','{"stem":"\"The power ceased the ___ her hands got wet.\"(the ___=一…就…:引导时间从句,填名词)","options":["since","time","moment","while"],"answer_index":2,"stem_cn":"她的手一沾湿,那能力就消失了。","explanation_cn":"the moment=“一…就…”,引导时间从句;用名词 moment。✓ the moment her hands got wet. ✗ time / while / since:此固定说法用 the moment。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp4','choice','{"stem":"\"She was able ___ describe the coins inside the safe.\"(be able + 不定式:填不定式符号)","options":["that","to","of","for"],"answer_index":1,"stem_cn":"她能描述保险箱里的硬币。","explanation_cn":"be able + 不定式;填不定式符号 to。✓ She was able to describe the coins. ✗ for / of / that:be able 后用 to do。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp5','choice','{"stem":"\"She asked ___ so many old coins had been kept there.\"(疑问词从句,填‘为什么’)","options":["why","that","so","which"],"answer_index":0,"stem_cn":"她问为什么那里存了那么多旧硬币。","explanation_cn":"疑问副词 why 引导从句,“为什么”。✓ asked why so many coins had been kept there. ✗ which / that / so:问原因用 why。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp5','choice','{"stem":"\"The scientists could not explain ___ she did it.\"(疑问词从句,填‘怎样’)","options":["whose","who","how","what"],"answer_index":2,"stem_cn":"科学家无法解释她是怎么做到的。","explanation_cn":"疑问副词 how 引导从句,“怎样、如何”。✓ could not explain how she did it. ✗ what / who / whose:问方式用 how。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp5','choice','{"stem":"\"No one knew ___ her strange gift came from.\"(疑问词从句,填‘从哪里’)","options":["that","where","when","which"],"answer_index":1,"stem_cn":"没人知道她这奇特天赋从何而来。","explanation_cn":"疑问副词 where 引导从句,“从哪里”。✓ knew where her gift came from. ✗ when / that / which:问地点/来源用 where。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp6','choice','{"stem":"\"Not letting light through means ___.\"(“不透明的”用哪个词)","options":["bright","clear","thin","opaque"],"answer_index":3,"stem_cn":"不让光透过的。","explanation_cn":"不让光透过的是 opaque。✓ read through an opaque screen. ✗ clear 透明;✗ bright 明亮;✗ thin 薄——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp6','choice','{"stem":"\"To become aware of something through the senses is to ___ it.\"(“感知”用哪个词)","options":["hide","perceive","forget","break"],"answer_index":1,"stem_cn":"通过感官觉察到某物。","explanation_cn":"通过感官觉察到某物是 perceive。✓ perceive shapes and colors. ✗ forget 忘记;✗ hide 隐藏;✗ break 打破——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',5,'am4_l4_gp6','choice','{"stem":"\"To stop happening is to ___.\"(“停止”用哪个词)","options":["spread","begin","cease","grow"],"answer_index":2,"stem_cn":"不再发生、停止。","explanation_cn":"不再发生、停止是 cease。✓ the ability ceased. ✗ begin 开始;✗ grow 生长;✗ spread 蔓延——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"perceive 的意思是:","options":["破坏","感知,察觉","隐藏","忘记"],"answer_index":1,"explanation_cn":"perceive = 感知、察觉。✓ perceive shapes and colors 感知形状与颜色。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"sensitivity 的意思是:","options":["麻木","力量","敏感(性),灵敏度","速度"],"answer_index":2,"explanation_cn":"sensitivity = 敏感性、灵敏度。✓ a similar sensitivity 类似的敏感度。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"opaque 的意思是:","options":["透明的","薄的","明亮的","不透明的"],"answer_index":3,"explanation_cn":"opaque = 不透明的。✓ an opaque screen 一块不透明的屏。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"commission 的意思是:","options":["工厂","委员会","军队","学校"],"answer_index":1,"explanation_cn":"commission = 委员会。✓ a special commission 一个专门委员会。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"outline 的意思是:","options":["轮廓","颜色","气味","重量"],"answer_index":0,"explanation_cn":"outline = 轮廓。✓ traced the outline of a picture 描出画的轮廓。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',6,NULL,'choice','{"stem":"cease 的意思是:","options":["开始","停止","生长","继续"],"answer_index":1,"explanation_cn":"cease = 停止。✓ the ability ceased 那能力停止了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',7,NULL,'cloze','{"stem":"第 1 空","context":"Several cases have ___1___ reported of people able to perceive colors with their skin. A girl ___2___ has normal vision can also ''see'' with her hands. Moving her elbow over some cards, she was able ___3___ name each color. The power ceased the ___4___ her hands got wet.","blank_no":1,"options":["been","be","being","was"],"answer_index":0,"explanation_cn":"现在完成的被动 have + been + 过去分词。✓ cases have been reported."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',7,NULL,'cloze','{"stem":"第 2 空","context":"Several cases have ___1___ reported of people able to perceive colors with their skin. A girl ___2___ has normal vision can also ''see'' with her hands. Moving her elbow over some cards, she was able ___3___ name each color. The power ceased the ___4___ her hands got wet.","blank_no":2,"options":["who","which","what","whom"],"answer_index":0,"explanation_cn":"定语从句,指人,who 作从句主语。✓ A girl who has normal vision."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',7,NULL,'cloze','{"stem":"第 3 空","context":"Several cases have ___1___ reported of people able to perceive colors with their skin. A girl ___2___ has normal vision can also ''see'' with her hands. Moving her elbow over some cards, she was able ___3___ name each color. The power ceased the ___4___ her hands got wet.","blank_no":3,"options":["to","for","of","that"],"answer_index":0,"explanation_cn":"be able + 不定式,填 to。✓ she was able to name each color."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',7,NULL,'cloze','{"stem":"第 4 空","context":"Several cases have ___1___ reported of people able to perceive colors with their skin. A girl ___2___ has normal vision can also ''see'' with her hands. Moving her elbow over some cards, she was able ___3___ name each color. The power ceased the ___4___ her hands got wet.","blank_no":4,"options":["moment","time","while","since"],"answer_index":0,"explanation_cn":"the moment=“一…就…”,引导时间从句。✓ ceased the moment her hands got wet."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',8,NULL,'choice','{"stem":"How was the girl''s strange gift first discovered?","options":["A doctor found it during a checkup","She discovered it while blindfolded","She read about it in a book","Her mother noticed it when she laid her hand on a closed safe"],"answer_index":3,"explanation_cn":"录音说她的异能最早被母亲发现:她把手放在关着的保险箱上,竟说出了里面的硬币。✓ mother noticed, hand on safe."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',8,NULL,'choice','{"stem":"What could the girl do during the scientists'' tests?","options":["See through her closed eyes only","Move objects with her mind","Read print and name colors through an opaque screen","Predict the future"],"answer_index":2,"explanation_cn":"录音说测试中她能隔着不透明的屏读字,还能移动胳膊肘准确报出彩色卡片的颜色。✓ read print, name colors."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',8,NULL,'choice','{"stem":"When did the girl''s ability stop working?","options":["When she was blindfolded","The moment her hands were wet","In the dark","When she was tired"],"answer_index":1,"explanation_cn":"录音说她的手一沾湿,这种感知能力就立刻停止。✓ hands wet."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',9,NULL,'choice','{"stem":"你想说\"她的天赋最初是被母亲注意到的\"(被动语态):","options":["Her gift was first noticing by her mother.","Her gift was first noticed by her mother.","Her gift was first notice by her mother.","Her gift first noticed by her mother."],"answer_index":1,"explanation_cn":"被动语态:was + 过去分词 noticed,动作的承受者 Her gift 放句首,施动者用 by 引出;notice 须用过去分词、不能省 was、不用 -ing。✓ was first noticed by her mother. 场合:强调“被…注意到”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',9,NULL,'choice','{"stem":"你想说\"她把胳膊肘在卡片上移动,叫出每种颜色\"(现在分词作状语):","options":["To move her elbow over the cards, she named each color.","Moved her elbow over the cards, she named each color.","Moving her elbow over the cards, she named each color.","Move her elbow over the cards, she named each color."],"answer_index":2,"explanation_cn":"现在分词短语作状语用主动 Moving;不用 Moved(被动)、不用原形 Move、不用 To move。✓ Moving …, she named… 场合:表“一边…一边…/…时…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',9,NULL,'choice','{"stem":"你想说\"报告说的是能用手指辨色的人\"(定语从句):","options":["The report concerns people which can detect colors with their fingers.","The report concerns people can detect colors with their fingers.","The report concerns people what can detect colors with their fingers.","The report concerns people who can detect colors with their fingers."],"answer_index":3,"explanation_cn":"关系词 who 指人,引导修饰 people 的从句;不用 which(指物)、不用 what、也不能省去 who。✓ people who can detect colors. 场合:说“能…的那些人”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"perceive 的意思是:","options":["感知,察觉","忘记","破坏","隐藏"],"answer_index":0,"explanation_cn":"perceive = 感知、察觉。✓ perceive shapes and colors."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"opaque 的意思是:","options":["明亮的","不透明的","透明的","薄的"],"answer_index":1,"explanation_cn":"opaque = 不透明的。✓ an opaque screen."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"\"Several cases have ___ reported.\"(现在完成的被动:have + ___ + 过去分词,填这个词)","options":["was","be","been","being"],"answer_index":2,"stem_cn":"报道了几起怪事。","explanation_cn":"现在完成的被动 have + been + 过去分词。✓ cases have been reported. ✗ be / being / was。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"\"___ her elbow over the cards, she named each color.\"(现在分词作状语)","options":["To move","Move","Moved","Moving"],"answer_index":3,"stem_cn":"她把胳膊肘在卡片上移动,叫出每种颜色。","explanation_cn":"现在分词短语作状语,主动“移动…”。✓ Moving her elbow…, she named… ✗ Moved / Move / To move。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"\"make out\" 的意思是:","options":["加速","辨认出、看清","弄丢","拒绝"],"answer_index":1,"explanation_cn":"make out = 辨认出、看清。✓ make out the outline under the rug."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"\"a series of\" 的意思是:","options":["一连串、一系列","一半","一点点","偶尔"],"answer_index":0,"explanation_cn":"a series of = 一连串、一系列。✓ a series of tests."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"How did the girl first reveal her strange ability?","options":["She read a book in the dark","She solved a puzzle","She described coins locked inside a closed safe","She drew a picture"],"answer_index":2,"passage":"In recent years several strange cases have been reported of people who seem able to detect colors with their fingertips, or even to sense objects hidden behind a solid wall. One of the most remarkable concerns a young girl named Nadia, who has perfectly normal vision but who can also perceive shapes and colors through the skin of her hands. Her unusual gift was first noticed by her mother. One afternoon Nadia laid her hand on the closed door of a small safe and, without hesitation, described the coins locked inside and asked why so many old ones had been kept there. Word of her talent soon reached a group of scientists, and in the spring she was given a long series of tests by a special commission. During these tests she was able to read a page of print through an opaque screen; and, stranger still, moving her elbow slowly over a set of colored cards, she named each color correctly. In another test, wearing thick gloves, she traced with one finger the outline of a picture that had been hidden beneath a rug. The scientists found that her knees and shoulders showed a similar sensitivity. Throughout every trial Nadia was blindfolded; indeed, unless she was blindfolded she seemed to lose the power altogether. It was also discovered that, although she could perceive things with her fingers, the ability ceased the moment her hands were wet.","explanation_cn":"课文说她第一次显露异能,是把手放在关着的小保险箱上,说出了锁在里面的硬币。✓ described coins in the safe."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"What did the scientists find about her knees and shoulders?","options":["They showed a similar sensitivity","They were injured","They were completely numb","They were stronger than normal"],"answer_index":0,"passage":"In recent years several strange cases have been reported of people who seem able to detect colors with their fingertips, or even to sense objects hidden behind a solid wall. One of the most remarkable concerns a young girl named Nadia, who has perfectly normal vision but who can also perceive shapes and colors through the skin of her hands. Her unusual gift was first noticed by her mother. One afternoon Nadia laid her hand on the closed door of a small safe and, without hesitation, described the coins locked inside and asked why so many old ones had been kept there. Word of her talent soon reached a group of scientists, and in the spring she was given a long series of tests by a special commission. During these tests she was able to read a page of print through an opaque screen; and, stranger still, moving her elbow slowly over a set of colored cards, she named each color correctly. In another test, wearing thick gloves, she traced with one finger the outline of a picture that had been hidden beneath a rug. The scientists found that her knees and shoulders showed a similar sensitivity. Throughout every trial Nadia was blindfolded; indeed, unless she was blindfolded she seemed to lose the power altogether. It was also discovered that, although she could perceive things with her fingers, the ability ceased the moment her hands were wet.","explanation_cn":"课文说科学家发现,她的膝盖和肩膀也有类似的敏感度。✓ similar sensitivity."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"What condition made the girl lose her power to perceive?","options":["Loud noise","Her hands becoming wet","Bright light","Being watched"],"answer_index":1,"audio":"In recent years several strange cases have been reported of people who seem able to detect colors with their fingertips, or even to sense objects hidden behind a solid wall. One of the most remarkable concerns a young girl named Nadia, who has perfectly normal vision but who can also perceive shapes and colors through the skin of her hands. Her unusual gift was first noticed by her mother. One afternoon Nadia laid her hand on the closed door of a small safe and, without hesitation, described the coins locked inside and asked why so many old ones had been kept there. Word of her talent soon reached a group of scientists, and in the spring she was given a long series of tests by a special commission. During these tests she was able to read a page of print through an opaque screen; and, stranger still, moving her elbow slowly over a set of colored cards, she named each color correctly. In another test, wearing thick gloves, she traced with one finger the outline of a picture that had been hidden beneath a rug. The scientists found that her knees and shoulders showed a similar sensitivity. Throughout every trial Nadia was blindfolded; indeed, unless she was blindfolded she seemed to lose the power altogether. It was also discovered that, although she could perceive things with her fingers, the ability ceased the moment her hands were wet.","explanation_cn":"课文说她的手一沾湿,这种感知能力就停止了。✓ hands wet."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l4',10,NULL,'choice','{"stem":"Under what condition could she perceive things best?","options":["When she wore gloves","When she was asleep","When her eyes were open","When she was blindfolded"],"answer_index":3,"audio":"In recent years several strange cases have been reported of people who seem able to detect colors with their fingertips, or even to sense objects hidden behind a solid wall. One of the most remarkable concerns a young girl named Nadia, who has perfectly normal vision but who can also perceive shapes and colors through the skin of her hands. Her unusual gift was first noticed by her mother. One afternoon Nadia laid her hand on the closed door of a small safe and, without hesitation, described the coins locked inside and asked why so many old ones had been kept there. Word of her talent soon reached a group of scientists, and in the spring she was given a long series of tests by a special commission. During these tests she was able to read a page of print through an opaque screen; and, stranger still, moving her elbow slowly over a set of colored cards, she named each color correctly. In another test, wearing thick gloves, she traced with one finger the outline of a picture that had been hidden beneath a rug. The scientists found that her knees and shoulders showed a similar sensitivity. Throughout every trial Nadia was blindfolded; indeed, unless she was blindfolded she seemed to lose the power altogether. It was also discovered that, although she could perceive things with her fingers, the ability ceased the moment her hands were wet.","explanation_cn":"课文说整个测试她都被蒙着眼;只要不蒙眼,她反而失去这种能力。✓ blindfolded."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l5',4,1,5,'Youth','青年','强调句(It is/was … that/who …)、as if/as though + were(与现在相反的虚拟)、would have done(与过去相反的虚拟)+ 被动不定式 to be done、动名词作主语/宾语、祈使句 let us + 方位介词对比(NCE4 无 KS 页,考点由课文结构自取;原创承载·论‘青年问题’实为长辈所造、青年是自由可爱的平等的人的随笔·题材无害;美语化 favorite/realize;第四册第5课)','人们总在谈论所谓的“青年问题”。倘若这样的问题真的存在——对此我斗胆表示怀疑——那么制造它的多半是老一辈,而不是年轻人自己。让我们回到根本上来,先承认这一点:年轻人归根结底也是人,和他们的长辈没什么两样。老年人和年轻人之间其实只有一个区别:年轻人前程似锦,而老年人辉煌已成往事——也许症结正在于此。我自己还是少年时,只觉得自己年轻、对一切都没把握;那时若有谁称我是个“问题”,我准会高兴——被看作这么有趣的东西,何乐而不为。说到底,当个“问题”反倒给人一种身份感,而身份正是年轻人一直在苦苦寻找的东西之一。我觉得年轻人很有意思。他们身上有一股自由的气息,不像我们背负着对蝇头小利或安逸生活那种沉闷的执念。他们不是焦虑的钻营者,也不迷恋物质。这一切在我看来把他们和生命、和万物的本源连在了一起;仿佛他们是宇宙的生灵,与我们这些乏味的郊区俗人形成鲜明可爱的对照。年轻人也许自负、无礼、甚至有点傻;可我并不躲进那些关于“敬老”的陈词滥调里去,好像光凭年纪大就该受人尊敬似的。我认定我们是平等的;倘若我认为一个年轻人错了,我会像对平辈那样和他争辩。','{"q":"Listen and answer — How does the writer like to treat young people?","options":["As his equals","As problems to be fixed","As children to be guided","With suspicion"],"answer_index":0}'::jsonb,'{"title":"强调句 / as if + were / would have done + 被动不定式 / 动名词作主语","intro":"①强调句 It is/was + 被强调部分 + that/who + 其余;强调人可用 who。②as if/as though + were(be 一律用 were),表与现在相反的虚拟。③与过去相反的虚拟:would + have + 过去分词;被动不定式 to be + 过去分词。④动名词可作主语/宾语:Being a problem gives…;feel no devotion to…。⑤祈使句 Let us + 动词原形。","table":{"headers":["用法","结构","例子"],"rows":[["强调句","It is … that/who …","It is older people who create it"],["as if + 虚拟","as if + were / had done","as if they were cosmic beings"],["与过去相反虚拟","would + have + 过去分词","I would have been pleased"],["动名词作主语","Doing … + 谓语","Being a problem gives identity"]]},"specialRules":[{"rule":"as if / as though 后表与现在相反的虚拟时,be 一律用 were(即使主语是单数)。","mark":"as if they were / as if age were"},{"rule":"被动不定式=to be + 过去分词:to be thought interesting、to be regarded as…。","mark":"to be thought / to be regarded"},{"rule":"美式拼写:favorite(最喜爱的,英式 favourite)、realize(意识到,英式 realise)。本课已按美语写。","mark":"favorite / realize"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l5',1,NULL,'People are forever talking about ''the problem of youth.'' If such a problem exists at all — which I take leave to doubt — then it is surely the older generation that has created it, and not the young themselves. Let us get down to fundamentals and agree that the young are, after all, human beings, people very much like their elders.','人们总在谈论所谓的“青年问题”。倘若这样的问题真的存在——对此我斗胆表示怀疑——那么制造它的多半是老一辈,而不是年轻人自己。让我们回到根本上来,先承认这一点:年轻人归根结底也是人,和他们的长辈没什么两样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l5',2,NULL,'There is really only one difference between an old man and a young one: the young man has a glorious future before him, while the old man has a splendid future behind him — and perhaps that is where the rub lies. When I was a teenager myself, I felt only that I was young and unsure of everything; had anyone called me ''a problem,'' I would have been delighted to be thought so interesting.','老年人和年轻人之间其实只有一个区别:年轻人前程似锦,而老年人辉煌已成往事——也许症结正在于此。我自己还是少年时,只觉得自己年轻、对一切都没把握;那时若有谁称我是个“问题”,我准会高兴——被看作这么有趣的东西,何乐而不为。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l5',3,NULL,'Being a problem, after all, gives a person a certain identity, and identity is one of the things the young are forever searching for. I find young people exciting. They have an air of freedom, and they carry no dreary commitment to mean ambitions or to the love of comfort.','说到底,当个“问题”反倒给人一种身份感,而身份正是年轻人一直在苦苦寻找的东西之一。我觉得年轻人很有意思。他们身上有一股自由的气息,不像我们背负着对蝇头小利或安逸生活那种沉闷的执念。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l5',4,NULL,'They are not anxious social climbers, and they feel no devotion to material things. All this seems to link them with life, and with the very origins of things; it is as if they were cosmic beings, in vivid and lovely contrast with us dull suburban creatures.','他们不是焦虑的钻营者,也不迷恋物质。这一切在我看来把他们和生命、和万物的本源连在了一起;仿佛他们是宇宙的生灵,与我们这些乏味的郊区俗人形成鲜明可爱的对照。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l5',5,NULL,'A young person may be conceited, ill-mannered, even foolish; but I do not turn for shelter to the tired cliches about respect for one''s elders, as if age alone were any reason for respect. I take it that we are equals, and if I believe a young man is wrong, I will argue with him as an equal.','年轻人也许自负、无礼、甚至有点傻;可我并不躲进那些关于“敬老”的陈词滥调里去,好像光凭年纪大就该受人尊敬似的。我认定我们是平等的;倘若我认为一个年轻人错了,我会像对平辈那样和他争辩。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
