INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l5','get down to','',NULL,'/ɡet daʊn tə/','Let us get down to fundamentals.','让我们回到根本上来。','It''s time to get down to business.','该认真办正事了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l5','in contrast with','',NULL,'/ɪn ˈkɑːntræst wɪð/','The young are in lovely contrast with us.','年轻人与我们形成可爱的对照。','Her calm was in contrast with his panic.','她的镇定与他的慌乱形成对比。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l5','search for','',NULL,'/sɜːrtʃ fɔːr/','Identity is what the young are searching for.','身份正是年轻人所追寻的。','They searched for a better life.','他们追寻更好的生活。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l5','turn to','',NULL,'/tɜːrn tə/','I do not turn to tired cliches for shelter.','我不躲进陈词滥调里去。','She turned to her friend for advice.','她向朋友求教。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp1','choice','{"stem":"\"It is older people ___ create the so-called problem of youth.\"(强调句,被强调的是指人的 people,填相应的关系词)","options":["who","which","what","whose"],"answer_index":0,"stem_cn":"正是长辈制造了所谓的青年问题。","explanation_cn":"强调句 It is + 被强调的 older people + who…;被强调的是人,用 who。✓ It is older people who create it. ✗ which(指物)/ what / whose:强调人用 who。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp1','choice','{"stem":"\"It ___ the older generation that created the problem, not the young.\"(强调句,一般过去,填 be 动词)","options":["did","was","is","has"],"answer_index":1,"stem_cn":"是老一辈制造了这个问题,而非年轻人。","explanation_cn":"强调句 It + be + …；此处叙述过去,be 用 was。✓ It was the older generation that created… ✗ is(时态不符)/ has / did:过去用 was。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp1','choice','{"stem":"\"It is identity ___ the young are always searching for.\"(强调句,被强调的是物 identity,填相应的关系词)","options":["that","what","who","whose"],"answer_index":0,"stem_cn":"年轻人一直在寻找的正是身份认同。","explanation_cn":"强调句,被强调的是物 identity,连接词用 that。✓ It is identity that the young search for. ✗ who(指人)/ what / whose:强调物用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp2','choice','{"stem":"\"It is as if they ___ cosmic beings from another world.\"(as if + 与现在相反虚拟,be 动词用哪种形式)","options":["was","are","were","be"],"answer_index":2,"stem_cn":"仿佛他们是来自另一个世界的宇宙生灵。","explanation_cn":"as if + 与现在相反的虚拟,be 一律用 were。✓ as if they were cosmic beings. ✗ was / are / be:虚拟里 be 用 were。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp2','choice','{"stem":"\"He speaks as if age ___ a reason for respect.\"(as if + 虚拟,be 动词的虚拟形式)","options":["was","being","is","were"],"answer_index":3,"stem_cn":"他说得好像上了年纪就该受人尊敬似的。","explanation_cn":"as if + 虚拟,即使主语 age 是单数,be 也用 were。✓ as if age were a reason for respect. ✗ is / was / being:虚拟用 were。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp2','choice','{"stem":"\"They act as if they ___ nothing to fear.\"(as if + 虚拟,have 的过去式)","options":["having","has","had","have"],"answer_index":2,"stem_cn":"他们表现得仿佛无所畏惧。","explanation_cn":"as if + 虚拟,实义动词用过去式;have → had。✓ as if they had nothing to fear. ✗ have / has / having:虚拟用过去式 had。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp3','choice','{"stem":"\"Had anyone called me a problem, I ___ have been pleased.\"(与过去相反虚拟,主句填这个助动词 + have + 过去分词)","options":["must","would","will","can"],"answer_index":1,"stem_cn":"要是当年有人说我是个问题,我会很高兴。","explanation_cn":"与过去相反的虚拟,主句用 would + have + 过去分词。✓ I would have been pleased. ✗ will / can / must:主句用 would。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp3','choice','{"stem":"\"I would have been delighted ___ be thought so interesting.\"(被动不定式(… be + 过去分词):填最前面的不定式符号)","options":["to","for","of","that"],"answer_index":0,"stem_cn":"被认为那么有趣,我会很高兴。","explanation_cn":"被动不定式 to be + 过去分词;填不定式符号 to。✓ delighted to be thought so interesting. ✗ for / of / that:此处用 to be thought。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp3','choice','{"stem":"\"I would have been glad to ___ regarded as a problem.\"(被动不定式:to + ___ + 过去分词,填中间这个词)","options":["been","be","being","was"],"answer_index":1,"stem_cn":"被当成一个问题,我会很乐意。","explanation_cn":"被动不定式 to + be + 过去分词;填中间的 be。✓ glad to be regarded as a problem. ✗ being / been / was:不定式里用原形 be。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp4','choice','{"stem":"\"___ a problem gives a person a certain identity.\"(动名词作主语,主动“成为…”)","options":["Be","To being","Being","Been"],"answer_index":2,"stem_cn":"成为一个问题,反倒给人一种身份。","explanation_cn":"动名词作主语,主动“成为…”。✓ Being a problem gives a person identity. ✗ Been / Be / To being:作主语用动名词 Being。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp4','choice','{"stem":"\"The young feel no ___ to material things.\"(feel no ___ to sth:对…的迷恋/热爱,填名词)","options":["devote","devoted","devoting","devotion"],"answer_index":3,"stem_cn":"年轻人对物质毫无迷恋。","explanation_cn":"feel no devotion to sth,“对…没有热爱/迷恋”;此处填名词 devotion。✓ feel no devotion to material things. ✗ devote(动词)/ devoted / devoting:此处需名词 devotion。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp4','choice','{"stem":"\"The young are not interested in ___ comfort above all.\"(介词 in 后用动名词,填 -ing 形式)","options":["loving","love","loved","to love"],"answer_index":0,"stem_cn":"年轻人无意于把安逸看得高于一切。","explanation_cn":"介词 in 后用动名词;love → loving。✓ interested in loving comfort above all. ✗ love / loved / to love:介词后用 -ing。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp5','choice','{"stem":"\"___ get down to fundamentals and agree on one thing.\"(祈使句“让我们…”,填句首这个动词)","options":["Make","Let","Do","Have"],"answer_index":1,"stem_cn":"让我们回到根本,先达成一点共识。","explanation_cn":"祈使句“让我们…”用 Let us + 动词原形。✓ Let us get down to fundamentals. ✗ Make / Have / Do:此句型用 Let。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp5','choice','{"stem":"\"The young man has a glorious future ___ him, the old one behind him.\"(方位介词对比,填‘在…前面’)","options":["after","under","before","behind"],"answer_index":2,"stem_cn":"年轻人前程似锦,老年人辉煌已成往事。","explanation_cn":"方位介词对比:未来在“前面”用 before(过去在“后面”用 behind)。✓ a glorious future before him. ✗ after / behind / under:“在…前面”用 before。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp5','choice','{"stem":"\"I take ___ to doubt that such a problem exists at all.\"(take ___ to do:冒昧地做…,填名词)","options":["place","part","care","leave"],"answer_index":3,"stem_cn":"我冒昧地怀疑,这样的问题是否真的存在。","explanation_cn":"take leave to do,“冒昧地做…”;固定用名词 leave。✓ I take leave to doubt. ✗ place / part / care:固定搭配是 take leave to do。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp6','choice','{"stem":"\"Dull, gloomy and boring means ___.\"(“沉闷的”用哪个词)","options":["dreary","cheerful","exciting","bright"],"answer_index":0,"stem_cn":"沉闷、乏味、令人厌倦的。","explanation_cn":"沉闷、乏味、令人厌倦的是 dreary。✓ no dreary commitment. ✗ cheerful 愉快;✗ exciting 令人兴奋;✗ bright 明亮——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp6','choice','{"stem":"\"Too proud of oneself means ___.\"(“自负的”用哪个词)","options":["modest","kind","shy","conceited"],"answer_index":3,"stem_cn":"过于自以为是的。","explanation_cn":"过于自以为是的是 conceited。✓ a young person may be conceited. ✗ modest 谦虚;✗ shy 害羞;✗ kind 善良——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',5,'am4_l5_gp6','choice','{"stem":"\"An overused, unoriginal phrase is a ___.\"(“陈词滥调”用哪个词)","options":["promise","secret","cliche","poem"],"answer_index":2,"stem_cn":"被用滥了、毫无新意的说法。","explanation_cn":"被用滥了、毫无新意的说法是 cliche。✓ the tired cliches about respect. ✗ poem 诗;✗ secret 秘密;✗ promise 承诺——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"fundamentals 的意思是:","options":["例外","细节","基本原则,根本","结论"],"answer_index":2,"explanation_cn":"fundamentals = 基本原则、根本。✓ get down to fundamentals 回到根本。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"glorious 的意思是:","options":["短暂的","光辉灿烂的","平凡的","黯淡的"],"answer_index":1,"explanation_cn":"glorious = 光辉灿烂的。✓ a glorious future 灿烂的前程。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"splendid 的意思是:","options":["辉煌的,极好的","廉价的","普通的","糟糕的"],"answer_index":0,"explanation_cn":"splendid = 辉煌的、极好的。✓ a splendid future behind him 辉煌已成往事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"identity 的意思是:","options":["职业","秘密","习惯","身份,特性"],"answer_index":3,"explanation_cn":"identity = 身份、特性。✓ a certain identity 一种身份感。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"commitment 的意思是:","options":["拒绝","信奉,执念","冷漠","怀疑"],"answer_index":1,"explanation_cn":"commitment = 信奉、执念、投入。✓ no dreary commitment 没有沉闷的执念。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',6,NULL,'choice','{"stem":"cosmic 的意思是:","options":["宇宙的","地方的","日常的","家庭的"],"answer_index":0,"explanation_cn":"cosmic = 宇宙的。✓ cosmic beings 宇宙的生灵。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',7,NULL,'cloze','{"stem":"第 1 空","context":"If a ''problem of youth'' exists — which I doubt — it is the older people ___1___ create it, not the young. Let us ___2___ down to fundamentals: the young are people too. ___3___ a problem even gives one a new identity. It is as if they ___4___ beings from another world.","blank_no":1,"options":["who","which","what","whose"],"answer_index":0,"explanation_cn":"强调句,被强调的是指人的 older people,用 who。✓ it is the older people who create it."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',7,NULL,'cloze','{"stem":"第 2 空","context":"If a ''problem of youth'' exists — which I doubt — it is the older people ___1___ create it, not the young. Let us ___2___ down to fundamentals: the young are people too. ___3___ a problem even gives one a new identity. It is as if they ___4___ beings from another world.","blank_no":2,"options":["get","make","take","put"],"answer_index":0,"explanation_cn":"get down to,“认真着手”。✓ Let us get down to fundamentals."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',7,NULL,'cloze','{"stem":"第 3 空","context":"If a ''problem of youth'' exists — which I doubt — it is the older people ___1___ create it, not the young. Let us ___2___ down to fundamentals: the young are people too. ___3___ a problem even gives one a new identity. It is as if they ___4___ beings from another world.","blank_no":3,"options":["Being","Been","Be","To being"],"answer_index":0,"explanation_cn":"动名词作主语,“成为…”。✓ Being a problem gives one a new identity."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',7,NULL,'cloze','{"stem":"第 4 空","context":"If a ''problem of youth'' exists — which I doubt — it is the older people ___1___ create it, not the young. Let us ___2___ down to fundamentals: the young are people too. ___3___ a problem even gives one a new identity. It is as if they ___4___ beings from another world.","blank_no":4,"options":["were","was","are","be"],"answer_index":0,"explanation_cn":"as if + 与现在相反的虚拟,be 用 were。✓ as if they were beings from another world."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',8,NULL,'choice','{"stem":"How does the writer like to treat young people?","options":["With suspicion","As his equals, to be argued with if wrong","As problems to be solved","As children needing constant guidance"],"answer_index":1,"explanation_cn":"录音说作者把年轻人当平等的人看待:若认为对方错了,会像对平辈一样和他争辩。✓ as equals."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',8,NULL,'choice','{"stem":"According to the writer, who really creates ''the problem of youth''?","options":["Teachers","The government","Older people, not the young themselves","The young themselves"],"answer_index":2,"explanation_cn":"录音说作者认为所谓“青年问题”其实是老一辈制造的,而非年轻人自己。✓ older people create it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',8,NULL,'choice','{"stem":"Why does the writer find young people exciting?","options":["They have an air of freedom and no dreary commitments","They love comfort and money","They are quiet and modest","They always obey their elders"],"answer_index":0,"explanation_cn":"录音说作者觉得年轻人令人振奋,因为他们身上有一股自由气息,不背负沉闷的执念。✓ air of freedom."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',9,NULL,'choice','{"stem":"你想说\"正是长辈制造了所谓的青年问题\"(强调句):","options":["It is the older people which create the so-called problem of youth.","It is the older people whom create the so-called problem of youth.","It is the older people who create the so-called problem of youth.","Is the older people who create the so-called problem of youth."],"answer_index":2,"explanation_cn":"强调句 It is + 被强调的 older people + who…;被强调的是人用 who;句首 It is 不能省、不用 which/whom。✓ It is the older people who create… 场合:强调“正是…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',9,NULL,'choice','{"stem":"你想说\"仿佛他们是来自另一个世界的宇宙生灵\"(as if + 虚拟):","options":["It is as if they were cosmic beings from another world.","It is as if they be cosmic beings from another world.","It is as if they are cosmic beings from another world.","It is as if they was cosmic beings from another world."],"answer_index":0,"explanation_cn":"as if + 与现在相反的虚拟,be 一律用 were;不用 was、不用 are、不用 be。✓ as if they were cosmic beings. 场合:说“仿佛(其实并非)…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',9,NULL,'choice','{"stem":"你想说\"要是当年有人说我是个问题,我会很高兴\"(与过去相反虚拟):","options":["If anyone had called me a problem, I will have been pleased.","If anyone called me a problem, I would have been pleased.","If anyone had called me a problem, I would be pleased.","If anyone had called me a problem, I would have been pleased."],"answer_index":3,"explanation_cn":"与过去相反的虚拟:if 从句 had + 过去分词 called,主句 would + have + 过去分词 been;不用 would be、不用一般过去 called、不用 will have。✓ had called…, would have been pleased. 场合:对过去作与事实相反的假设。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"identity 的意思是:","options":["身份,特性","职业","秘密","习惯"],"answer_index":0,"explanation_cn":"identity = 身份、特性。✓ a certain identity."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"dreary 的意思是:","options":["明亮的","沉闷的,乏味的","短暂的","快乐的"],"answer_index":1,"explanation_cn":"dreary = 沉闷的、乏味的。✓ no dreary commitment."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"\"It is older people ___ create the problem of youth.\"(强调句,强调指人)","options":["who","whose","what","which"],"answer_index":0,"stem_cn":"正是长辈制造了青年问题。","explanation_cn":"强调句,被强调的是指人的 older people,用 who。✓ It is older people who create it. ✗ which / what / whose。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"\"It is as if they ___ cosmic beings.\"(as if + 与现在相反虚拟)","options":["was","are","be","were"],"answer_index":3,"stem_cn":"仿佛他们是宇宙的生灵。","explanation_cn":"as if + 与现在相反的虚拟,be 用 were。✓ as if they were cosmic beings. ✗ was / are / be。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"\"get down to\" 的意思是:","options":["减少","认真着手(做)","下车","放下"],"answer_index":1,"explanation_cn":"get down to = 认真着手(做某事)。✓ get down to fundamentals."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"\"in contrast with\" 的意思是:","options":["与…形成对比","靠近","与…一致","属于"],"answer_index":0,"explanation_cn":"in contrast with = 与…形成对比。✓ in lovely contrast with us."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"What does the writer say is the only real difference between the old and the young?","options":["The old are freer","The young are wiser","The young have their future ahead, the old have theirs behind","There is no difference at all"],"answer_index":2,"passage":"People are forever talking about ''the problem of youth.'' If such a problem exists at all — which I take leave to doubt — then it is surely the older generation that has created it, and not the young themselves. Let us get down to fundamentals and agree that the young are, after all, human beings, people very much like their elders. There is really only one difference between an old man and a young one: the young man has a glorious future before him, while the old man has a splendid future behind him — and perhaps that is where the rub lies. When I was a teenager myself, I felt only that I was young and unsure of everything; had anyone called me ''a problem,'' I would have been delighted to be thought so interesting. Being a problem, after all, gives a person a certain identity, and identity is one of the things the young are forever searching for. I find young people exciting. They have an air of freedom, and they carry no dreary commitment to mean ambitions or to the love of comfort. They are not anxious social climbers, and they feel no devotion to material things. All this seems to link them with life, and with the very origins of things; it is as if they were cosmic beings, in vivid and lovely contrast with us dull suburban creatures. A young person may be conceited, ill-mannered, even foolish; but I do not turn for shelter to the tired cliches about respect for one''s elders, as if age alone were any reason for respect. I take it that we are equals, and if I believe a young man is wrong, I will argue with him as an equal.","explanation_cn":"课文说老少之间唯一真正的区别是:年轻人前程在前,老年人辉煌在后。✓ future before/behind."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"Why does the writer refuse to demand respect merely for his age?","options":["He treats the young as equals and will argue only on merit","He dislikes young people","He is not old enough","He thinks age deserves no notice at all"],"answer_index":0,"passage":"People are forever talking about ''the problem of youth.'' If such a problem exists at all — which I take leave to doubt — then it is surely the older generation that has created it, and not the young themselves. Let us get down to fundamentals and agree that the young are, after all, human beings, people very much like their elders. There is really only one difference between an old man and a young one: the young man has a glorious future before him, while the old man has a splendid future behind him — and perhaps that is where the rub lies. When I was a teenager myself, I felt only that I was young and unsure of everything; had anyone called me ''a problem,'' I would have been delighted to be thought so interesting. Being a problem, after all, gives a person a certain identity, and identity is one of the things the young are forever searching for. I find young people exciting. They have an air of freedom, and they carry no dreary commitment to mean ambitions or to the love of comfort. They are not anxious social climbers, and they feel no devotion to material things. All this seems to link them with life, and with the very origins of things; it is as if they were cosmic beings, in vivid and lovely contrast with us dull suburban creatures. A young person may be conceited, ill-mannered, even foolish; but I do not turn for shelter to the tired cliches about respect for one''s elders, as if age alone were any reason for respect. I take it that we are equals, and if I believe a young man is wrong, I will argue with him as an equal.","explanation_cn":"课文说作者不因年长就要求尊敬,而是把年轻人当平等的人,只按对错与之争辩。✓ treats as equals."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"How does the writer treat a young person he thinks is wrong?","options":["He punishes him","He agrees to avoid conflict","He argues with him as an equal","He ignores him"],"answer_index":2,"audio":"People are forever talking about ''the problem of youth.'' If such a problem exists at all — which I take leave to doubt — then it is surely the older generation that has created it, and not the young themselves. Let us get down to fundamentals and agree that the young are, after all, human beings, people very much like their elders. There is really only one difference between an old man and a young one: the young man has a glorious future before him, while the old man has a splendid future behind him — and perhaps that is where the rub lies. When I was a teenager myself, I felt only that I was young and unsure of everything; had anyone called me ''a problem,'' I would have been delighted to be thought so interesting. Being a problem, after all, gives a person a certain identity, and identity is one of the things the young are forever searching for. I find young people exciting. They have an air of freedom, and they carry no dreary commitment to mean ambitions or to the love of comfort. They are not anxious social climbers, and they feel no devotion to material things. All this seems to link them with life, and with the very origins of things; it is as if they were cosmic beings, in vivid and lovely contrast with us dull suburban creatures. A young person may be conceited, ill-mannered, even foolish; but I do not turn for shelter to the tired cliches about respect for one''s elders, as if age alone were any reason for respect. I take it that we are equals, and if I believe a young man is wrong, I will argue with him as an equal.","explanation_cn":"课文说若认为一个年轻人错了,作者会像对平辈那样和他争辩。✓ argue as an equal."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l5',10,NULL,'choice','{"stem":"What quality does the writer most admire in the young?","options":["Their ambition for money","Their love of comfort","Their respect for elders","Their air of freedom"],"answer_index":3,"audio":"People are forever talking about ''the problem of youth.'' If such a problem exists at all — which I take leave to doubt — then it is surely the older generation that has created it, and not the young themselves. Let us get down to fundamentals and agree that the young are, after all, human beings, people very much like their elders. There is really only one difference between an old man and a young one: the young man has a glorious future before him, while the old man has a splendid future behind him — and perhaps that is where the rub lies. When I was a teenager myself, I felt only that I was young and unsure of everything; had anyone called me ''a problem,'' I would have been delighted to be thought so interesting. Being a problem, after all, gives a person a certain identity, and identity is one of the things the young are forever searching for. I find young people exciting. They have an air of freedom, and they carry no dreary commitment to mean ambitions or to the love of comfort. They are not anxious social climbers, and they feel no devotion to material things. All this seems to link them with life, and with the very origins of things; it is as if they were cosmic beings, in vivid and lovely contrast with us dull suburban creatures. A young person may be conceited, ill-mannered, even foolish; but I do not turn for shelter to the tired cliches about respect for one''s elders, as if age alone were any reason for respect. I take it that we are equals, and if I believe a young man is wrong, I will argue with him as an equal.","explanation_cn":"课文说作者最欣赏年轻人身上那股自由的气息。✓ an air of freedom."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
